// daily-data.js — the content the homepage "For today" feed draws from.
// Each array is picked deterministically by the day number, so the same item
// shows all day and cycles with Shuffle. Add freely; keep sources honest.
//
//   QUOTES    — a single line from a great mind (the hero card)
//   THOUGHTS  — a short paragraph to turn over during the day
//   VERSES    — a poem / psalm / maxim to hold in memory (recited across a week)
//   PASSAGES  — a longer excerpt from a great work, to read slowly
//   WORDS     — a Latin or Greek word, its root and English descendants
//
// The "one thing to do today" card is built from the practice lists already in
// arts-data.js, so it needs no data here.

window.QUOTES = [
  { text: 'You have power over your mind — not outside events. Realize this, and you will find strength.', author: 'Marcus Aurelius', source: 'Meditations', school: 'stoicism' },
  { text: 'It is not that we have a short time to live, but that we waste a great deal of it.', author: 'Seneca', source: 'On the Shortness of Life', school: 'stoicism' },
  { text: 'It is not things that disturb us, but our judgements about things.', author: 'Epictetus', source: 'Enchiridion', school: 'stoicism' },
  { text: 'The unexamined life is not worth living.', author: 'Socrates', source: 'Plato, Apology', school: 'platonism' },
  { text: 'We are what we repeatedly do. Excellence, then, is not an act but a habit.', author: 'after Aristotle', source: 'Nicomachean Ethics', school: 'aristotle' },
  { text: 'No man ever steps in the same river twice, for it is not the same river and he is not the same man.', author: 'Heraclitus', source: 'Fragments' },
  { text: 'The life of money-getting is one undertaken under compulsion, and wealth is evidently not the good we are seeking; for it is merely useful, for the sake of something else.', author: 'Aristotle', source: 'Nicomachean Ethics', school: 'aristotle' },
  { text: 'Not to be pleased with vice, but to be pleased with virtue — this is the beginning of wisdom.', author: 'Cicero', source: 'On Duties' },
  { text: 'By three methods we may learn wisdom: by reflection, which is noblest; by imitation, which is easiest; and by experience, which is the bitterest.', author: 'Confucius', source: 'Analects', school: 'confucius' },
  { text: 'Death does not concern us, because as long as we exist, death is not here. And when it does come, we no longer exist.', author: 'Epicurus', source: 'Letter to Menoeceus', school: 'epicureanism' },
  { text: 'I am not an Athenian or a Greek, but a citizen of the world.', author: 'Diogenes', source: 'reported by Diogenes Laërtius', school: 'cynicism' },
  { text: 'Nothing that is really good and admirable is granted by the gods to men without some effort and application.', author: 'Xenophon', source: 'Memorabilia' },
  { text: 'Waste no more time arguing about what a good man should be. Be one.', author: 'Marcus Aurelius', source: 'Meditations', school: 'stoicism' },
  { text: 'Wonder is the beginning of philosophy.', author: 'after Plato & Aristotle', source: 'Theaetetus / Metaphysics', school: 'platonism' },
  { text: 'We suffer more often in imagination than in reality.', author: 'Seneca', source: 'Letters to Lucilius (Epistle XIII)', school: 'stoicism' },
  { text: 'Every night before going to sleep, ask yourself: what infirmity have I mastered today? what passion opposed? what temptation resisted? what virtue acquired?', author: 'Seneca', source: 'On Anger', school: 'stoicism' },
  { text: 'Make no more excuses; simply be a good man.', author: 'after Marcus Aurelius', source: 'Meditations, Book X', school: 'stoicism' },
  { text: 'The best revenge is not to be like your enemy.', author: 'Marcus Aurelius', source: 'Meditations, Book VI', school: 'stoicism' },
  { text: 'Confine yourself to the present.', author: 'Marcus Aurelius', source: 'Meditations, Book VII', school: 'stoicism' },
  { text: 'No man is free who is not master of himself.', author: 'after Epictetus', source: 'Discourses', school: 'stoicism' },
  { text: 'We have two ears and one mouth, so that we may listen more and talk the less.', author: 'Zeno of Citium', source: 'reported by Diogenes Laërtius', school: 'stoicism' },
  { text: 'Well-being is realized by small steps, but is truly no small thing.', author: 'Zeno of Citium', source: 'reported by Diogenes Laërtius', school: 'stoicism' },
  { text: 'The whole is more than the sum of its parts.', author: 'after Aristotle', source: 'Metaphysics', school: 'aristotle' },
  { text: 'Hope is a waking dream.', author: 'Aristotle', source: 'reported by Diogenes Laërtius', school: 'aristotle' },
  { text: 'The soul never thinks without a mental picture.', author: 'Aristotle', source: 'On the Soul (De Anima)', school: 'aristotle' },
  { text: 'Let no one ignorant of geometry enter here.', author: 'after Plato', source: 'inscription said to be over the Academy', school: 'platonism' },
  { text: 'Astronomy compels the soul to look upward, and leads us from this world to another.', author: 'after Plato', source: 'Republic, Book VII', school: 'platonism' },
  { text: 'Musical training is a more potent instrument than any other, because rhythm and harmony find their way into the inward places of the soul.', author: 'Plato', source: 'Republic, Book III', school: 'platonism' },
  { text: 'The beginning is the most important part of the work.', author: 'Plato', source: 'Republic, Book II', school: 'platonism' },
  { text: 'There is no royal road to geometry.', author: 'Euclid', source: 'reported by Proclus, to King Ptolemy' },
  { text: 'Give me a place to stand, and I will move the earth.', author: 'Archimedes', source: 'reported by Pappus of Alexandria' },
  { text: 'There is geometry in the humming of the strings, there is music in the spacing of the spheres.', author: 'attributed to Pythagoras', source: 'the Pythagorean tradition' },
  { text: 'The life of the dead is set in the memory of the living.', author: 'Cicero', source: 'Philippics' },
  { text: 'If you have a garden and a library, you have everything you need.', author: 'Cicero', source: 'Letters to Varro' },
  { text: 'While there is life, there is hope.', author: 'after Cicero', source: 'Letters to Atticus' },
  { text: 'The mind is not a vessel to be filled, but a fire to be kindled.', author: 'Plutarch', source: 'On Listening to Lectures' },
  { text: 'Music is a part of us, and either ennobles or degrades our behaviour.', author: 'after Boethius', source: 'De Institutione Musica' },
  { text: 'Nothing is miserable unless you think it so.', author: 'Boethius', source: 'The Consolation of Philosophy' },
  { text: 'Fortune, though she flatter, is never faithful.', author: 'after Boethius', source: 'The Consolation of Philosophy' },
  { text: 'You made us for yourself, and our heart is restless until it rests in you.', author: 'Augustine of Hippo', source: 'Confessions I.1' },
  { text: 'Nothing in excess.', author: 'Solon', source: 'inscribed at the Temple of Apollo at Delphi' },
  { text: 'Know thyself.', author: 'the Delphic maxim', source: 'inscribed at the Temple of Apollo at Delphi' },
  { text: "Consider your origin: you were not made to live like brutes, but to follow virtue and knowledge.", author: "Dante", source: "Inferno XXVI (Kline trans.)" },
  { text: "Like the generations of leaves are those of men.", author: "Homer", source: "Iliad VI (Kline trans.)" },
  { text: "The strong do what they can and the weak suffer what they must.", author: "the Athenian envoys", source: "Thucydides, History V (Crawley trans.)" },
  { text: "Man is but a reed, the most feeble thing in nature; but he is a thinking reed.", author: "Blaise Pascal", source: "Pens\u00e9es 347" },
  { text: "Read not to contradict and confute, nor to believe and take for granted, but to weigh and consider.", author: "Francis Bacon", source: "Of Studies (1625)" },
  { text: "Some books are to be tasted, others to be swallowed, and some few to be chewed and digested.", author: "Francis Bacon", source: "Of Studies (1625)" },
  { text: "I went to the woods because I wished to live deliberately.", author: "Henry David Thoreau", source: "Walden (1854)" },
  { text: "Man is the measure of all things.", author: "Protagoras", source: "reported by Plato, Theaetetus" },
  { text: "The road up and the road down are one and the same.", author: "Heraclitus", source: "Fragments" },
  { text: "Character is a man's guiding spirit.", author: "after Heraclitus", source: "Fragments (\u0113thos anthr\u014dp\u014di daim\u014dn)" },
  { text: "Nothing exists except atoms and empty space; everything else is opinion.", author: "after Democritus", source: "reported by Diogenes La\u00ebrtius" },
  { text: "Become such as you are, having learned what that is.", author: "Pindar", source: "Pythian Odes II" },
  { text: "Observe due measure \u2014 timing is in all things the most important factor.", author: "Hesiod", source: "Works and Days" },
  { text: "Badness is easy to get, in quantity; the gods have put sweat in front of goodness.", author: "after Hesiod", source: "Works and Days" },
  { text: "Life is short, and the art long.", author: "Hippocrates", source: "Aphorisms I.1" },
  { text: "Love conquers all \u2014 let us too yield to love.", author: "Virgil", source: "Eclogues X.69" },
  { text: "Perhaps one day it will be a pleasure to remember even these things.", author: "Virgil", source: "Aeneid I.203" },
  { text: "Let others praise the old times; I am glad I was born in these.", author: "Ovid", source: "Ars Amatoria III" },
  { text: "I am human, and I count nothing human alien to me.", author: "Terence", source: "The Self-Tormentor" },
  { text: "Anyone can hold the helm when the sea is calm.", author: "Publilius Syrus", source: "Sentences" },
  { text: "They make a desert and call it peace.", author: "Tacitus", source: "Agricola 30, in the mouth of Calgacus" },
  { text: "A sound mind in a sound body.", author: "Juvenal", source: "Satires X" },
  { text: "In these matters the only certainty is that nothing is certain.", author: "Pliny the Elder", source: "Natural History II" },
  { text: "As long as you live, keep learning how to live.", author: "Seneca", source: "Letters to Lucilius 76", school: "stoicism" },
  { text: "Wealth consists not in having great possessions, but in having few wants.", author: "after Epictetus", source: "Discourses", school: "stoicism" },
  { text: "The heaviest penalty for declining to rule is to be ruled by someone inferior to you.", author: "Plato", source: "Republic I", school: "platonism" },
  { text: "The law is reason free from passion.", author: "Aristotle", source: "Politics III", school: "aristotle" },
  { text: "Love, and do what you will.", author: "Augustine of Hippo", source: "Homilies on the First Epistle of John VII" },
  { text: "Beware the man of a single book.", author: "attributed to Thomas Aquinas", source: "the medieval schools" },
  { text: "In the land of the blind, the one-eyed man is king.", author: "Erasmus", source: "Adagia" },
  { text: "My life has been full of terrible misfortunes, most of which never happened.", author: "attributed to Montaigne", source: "in the spirit of Essays III" },
  { text: "What then can be a man's escort through life? One thing and one thing only \u2014 philosophy.", author: "Marcus Aurelius", source: "Meditations II.17 (Farquharson trans.)", school: "stoicism" },
];

window.THOUGHTS = [
  { text: "Begin the day by telling yourself: today I shall be meeting with interference, ingratitude, insolence, disloyalty, ill-will, and selfishness. But I have seen the beauty of good, and the ugliness of evil, and I know that the wrongdoer shares the same reason I do. None of them can hurt me, for no one can involve me in what is degrading — nor can I be angry with my kinsman. We were born to work together.", source: 'Marcus Aurelius, Meditations II.1' },
  { text: "Life is long enough, and a sufficiently generous amount has been given to us for the highest achievements if it were all well invested. But when it is wasted in heedless luxury and spent on no good activity, we are forced at last by death's final constraint to realise that it has passed away before we knew it was passing.", source: 'Seneca, On the Shortness of Life' },
  { text: 'Some things are within our power, and some are not. Within our power are opinion, aim, desire, aversion — in a word, whatever affairs are our own. Beyond our power are body, property, reputation, office — whatever is not properly our own affair. If you suppose that only to be your own which is your own, and what belongs to others such as it really is, then no one will ever compel you, no one will restrain you.', source: 'Epictetus, Enchiridion 1' },
  { text: 'Every action which is done in a social spirit, and which tends toward the good of society, is according to nature. Where does the good lie? In the intention. And what makes an action good? That it is done for the common benefit, and completed with justice.', source: 'after Marcus Aurelius, Meditations IX' },
  { text: 'The soul becomes dyed with the colour of its thoughts. Think, therefore, on such things as are in your power, and be content that you have them; and desire nothing so much as the good order of your own mind.', source: 'after Marcus Aurelius, Meditations V' },
  { text: 'Virtue is a mean between two vices — the one of excess, the other of deficiency. Courage stands between rashness and cowardice; generosity between prodigality and meanness. To find the mean is difficult, and belongs to the wise; anyone can grow angry, but to be angry with the right person, to the right degree, at the right time, for the right purpose, and in the right way — that is not easy.', source: 'after Aristotle, Nicomachean Ethics II' },
  { text: 'Happiness depends upon ourselves. Of all the things that wisdom provides for living one’s whole life in happiness, the greatest by far is the possession of friendship.', source: 'after Aristotle & Epicurus' },
  { text: 'The gem cannot be polished without friction, nor a man perfected without trials. When you meet difficulty, do not ask that it be lighter — ask instead to be stronger; and when it is over, count what it taught you.', source: 'in the manner of the Stoics' },
  { text: 'Retire into yourself. The mind that turns inward and rests upon itself finds a citadel no siege can reach. Withdraw there often — not to escape your work, but to return to it steadier. A brief and untroubled looking-within is enough to send you back renewed.', source: 'after Marcus Aurelius, Meditations IV' },
  { text: 'Do not spend the strength you have on grieving what you lack. Consider instead the goods already in your hands, and ask how you would long for them if they were not yours. Then hold them with a grateful, unclenched grip — glad while you have them, calm when they go. This is the whole art of contentment.', source: 'after Marcus Aurelius, Meditations VII' },
  { text: 'It is not the man who has too little who is poor, but the man who craves more. Set a limit drawn by nature, and you will be rich today. Ignore it, and no fortune will ever be large enough. Wealth is an ordered desire, not a full storehouse.', source: 'after Seneca, Letters 2' },
  { text: 'We suffer more often in imagination than in reality. The mind runs ahead and lives through griefs that never arrive, spending real fear on unreal harms. Bring the wandering thought back to this hour, where the trouble is smaller than it seemed. What is present is nearly always bearable.', source: 'after Seneca, Letters 13' },
  { text: 'Seek not that events should happen as you wish, but wish them to happen as they do — and your life will flow serenely. You cannot command the weather, the crowd, or another’s choice; you can command your own aim and assent. Guard that inner power well, and nothing outside can defeat you.', source: 'after Epictetus, Enchiridion 8' },
  { text: 'When something troubles you, remember: it is not the thing itself that disturbs you, but your judgement about the thing. Death is not terrible, or it would have seemed so to the wise; it is the opinion that death is terrible that frightens us. So when you are hindered or grieved, turn first to your own verdict, for that is where the remedy is kept.', source: 'after Epictetus, Enchiridion 5' },
  { text: 'There is a place beyond the shadows on the wall. The prisoner who is turned around and led up the rough ascent is dazzled at first by the light, and would gladly return to the familiar dark. But let the eyes adjust, and he sees the things themselves, and last of all the sun that makes them visible. Education is not pouring sight into blind eyes, but turning the whole soul toward the light it already can bear.', source: 'after Plato, Republic VII' },
  { text: 'The beautiful things we meet — a fair face, a just deed, a well-made bowl — are beautiful because they share, however faintly, in Beauty itself. Love them, but do not stop at them. Let each one be a step, and mount from the many beautiful things toward the one that does not fade, is not born and does not die, and lends its light to all the rest.', source: 'after Plato, Symposium' },
  { text: 'To learn, on this teaching, is to remember. The soul knew the eternal patterns before it entered the body, and the things of sense do not create knowledge but awaken it. When a truth in geometry suddenly feels not new but recognised, that is recollection stirring. Study, then, is a homecoming of the mind to what it always half-knew.', source: 'on the Platonic teaching of recollection' },
  { text: 'We become just by doing just acts, temperate by acting with temperance, brave by doing brave things. Excellence is not a feeling we are born with but a habit we build, one right action laid upon another until choosing well becomes second nature. So the whole difference lies in the small daily deeds, for by them the character is quietly cast.', source: 'after Aristotle, Nicomachean Ethics II' },
  { text: 'To know a thing fully is to see its four causes: what it is made of, the shape or form it has, what brought it about, and the end for which it exists. A bronze statue is bronze, and a likeness, and the sculptor’s work, and made to honour. Ask of anything not only how it came to be, but what it is for — for the end is the cause that gives the others their sense.', source: 'after Aristotle, Physics II' },
  { text: 'The happiest life is not one of amusement but of activity worthy of our best part. When the mind is at work on what is highest — contemplating truth for its own sake — a person is nearest to what is finest in being human. Such activity is loved for itself, wants nothing beyond itself, and can fill even a quiet hour with completeness.', source: 'after Aristotle, Nicomachean Ethics X' },
  { text: 'Let this fourfold remedy stay with you: the divine is not to be feared, death is nothing to us, what is good is easy to get, and what is dreadful is easy to endure. Where the self is dissolved there is no one left to suffer, so no terror waits there. Set these four in place, and the great fears fall away, leaving room for a calm and grateful joy.', source: 'after Epicurus, on the tetrapharmakos' },
  { text: 'Not every desire must be answered — only sort them. Some are natural and necessary, like food and shelter and friendship, and these are easily met. Some are natural but not necessary, and may be enjoyed lightly. And some are empty, planted by opinion, endless by design; loosen your grip on these, and you will find you were already rich.', source: 'after Epicurus, Letter to Menoeceus' },
  { text: 'Of all the things that wisdom gathers for a blessed life, the greatest by far is friendship. It is not chiefly the help friends give that we prize, but the confidence of knowing they are there. A shared table, a trusted ear, a companion in the good — these outweigh most of what the anxious crowd chases. Store up friends, and you store up joy.', source: 'after Epicurus, Principal Doctrines' },
  { text: 'Ask of each thing whether it is according to nature or only according to custom. Much of what we chase — status, ornament, the good opinion of strangers — is convention wearing the mask of necessity. Strip it back to what living truly needs, and you find you need very little. The one who wants least is nearest to the freedom of the gods.', source: 'in the manner of the Cynics' },
  { text: 'Self-sufficiency is a great wealth, for the one who can be content with a cloak, plain bread, and clear water carries his fortune within and cannot be robbed of it. Fortune may take the outward things, but she cannot take a mind that has already learned to do without them. Practise wanting little now, while you are strong, and no loss will ever find you unprepared.', source: 'in the manner of Diogenes and the Cynics' },
  { text: 'When the ruler asked how to govern, the answer was: govern yourself first, and the rest will follow like grass bending in the wind. If the names are set right — if father is truly father, friend truly friend, work truly done — then order grows of itself. Set right what you are called, and become it in full; from that small honesty a whole harmony can spread.', source: 'on the Confucian rectification of names' },
  { text: 'Benevolence is not far off. Whenever you wish to be settled and secure, help others to be settled; whenever you wish to reach your aim, help others to reach theirs. What you do not want done to yourself, do not do to another. The whole of goodness can be carried in a single day’s ordinary kindness, near at hand and always within reach.', source: 'on the Confucian teaching of ren' },
  { text: 'The exemplary person is at ease and does not fret; the small-minded person frets and is never at ease. Ritual and courtesy are not empty forms but the outward shape of inner respect, the way reverence learns to walk. Attend to how you greet, how you eat, how you honour those who came before — for character is built in the manner of small things done well.', source: 'on the Confucian teaching of li' },
  { text: 'Why do we labour at geometry, drawing figures that no ruler ever perfectly makes? Because the mind that grasps the eternal ratio of a circle is being lifted, quietly, from the fleeting to the changeless. The lines on the sand are only a ladder; the real ascent is the soul turning from shadows toward what always is. This is why the old schools set number and shape at the gate of wisdom.', source: 'in the manner of the Platonic liberal arts' },
  { text: 'Read the great books slowly, as you would eat a rich meal — a little, well chewed, is worth more than volumes swallowed whole. To read a language in its own tongue is to be admitted into another mind, to think a thought the way its first thinker shaped it. Attention is the whole discipline: to hold one page, one idea, one sentence, until it opens. What the eye skims, the soul does not keep.', source: 'in the manner of the liberal arts as a way of life' },
  { text: 'Memory is the soul’s vast storehouse, its halls and inner chambers holding all we have ever taken in. What we attend to, we lay up there; what we neglect scatters like smoke. So choose well what you carry into that treasury each day — a fine passage learned, a truth held fast — for a life is built from what the memory keeps and the mind returns to. Fill the storehouse with gold, not straw.', source: 'in the manner of Augustine on memory' },
  { text: "You do not control what happens. You control what you do about it, and what you tell yourself it means. Almost every hour of distress you will have today comes from the second thing being confused with the first.", source: "after Epictetus, Enchiridion" },
  { text: "When something goes wrong, do not ask whose fault it is. Ask what part of it was yours, deal with that part first, and notice how much smaller the problem gets once you stop needing someone else to move.", source: "after Marcus Aurelius, Meditations" },
  { text: "Look down on the whole thing from a great height for a moment \u2014 the crowds, the ceremonies, the journeys, the births and the deaths going on at once. Not to make yourself feel small, but to notice how much of what you are anxious about is a performance for an audience that does not exist.", source: "after Marcus Aurelius, Meditations IX.30" },
  { text: "Loss and change are the same event described by two different words. Only one of them makes you suffer. Watch which one you reach for today.", source: "after Marcus Aurelius, Meditations IX.35" },
  { text: "You will not always be doing this. Whatever you are hurrying through in order to get to the good part \u2014 this is the good part, or there isn't one.", source: "in the manner of the Stoics" },
  { text: "Set aside a day now and then on which you eat the plainest food and wear the roughest clothes, and ask yourself: is this what I was so afraid of? You are not practising suffering. You are finding out, while it is still your own decision, how little you actually need.", source: "after Seneca, Letters 18" },
  { text: "Never come home from a crowd with a character worse than the one you left with. Notice what a room does to you. Some rooms make you greedier, some make you crueller, and both do it while you are enjoying yourself.", source: "after Seneca, Letters 7" },
  { text: "You are not short of time. You are short of attention. The hours you cannot account for were not stolen from you \u2014 they were handed over, one small yes at a time.", source: "after Seneca, On the Shortness of Life" },
  { text: "Judge a man before you make him your friend, not after. But once you have made him your friend, speak to him as boldly as you speak to yourself. To trust everyone and to trust no one are equally lazy.", source: "after Seneca, Letters 3" },
  { text: "The point of a friend is not comfort. It is that a second honest person makes good fortune brighter by sharing it and bad fortune lighter by dividing it \u2014 and stops you believing your own account of yourself.", source: "after Cicero, On Friendship" },
  { text: "Gratitude is not a feeling, it is a debt. If a kindness has already been done to you, no duty comes before repaying it \u2014 and the fruitful field returns more than it received.", source: "after Cicero, On Duties I" },
  { text: "You did not become impatient today. You have been becoming impatient for years, one small permission at a time. Character is the sum of what you have repeatedly allowed.", source: "after Aristotle, Nicomachean Ethics II" },
  { text: "Virtue is a skill, not a rule. There is no formula that tells you how brave to be in this particular room, with these particular people, at this particular cost. You learn it the way you learn anything \u2014 badly at first, and by doing it.", source: "after Aristotle, Nicomachean Ethics II" },
  { text: "A person cut off from other people is not an independent human being. They are a hand cut from an arm, still called a hand out of politeness.", source: "after Aristotle, Politics I" },
  { text: "Notice how much you want to know things you will never use. Children ask what a thing is long before they could possibly need the answer. That appetite is not a means to anything. It is the thing itself.", source: "after Aristotle, Metaphysics I" },
  { text: "Do not tell me who a character is. Show me what he does. This is the oldest note ever given to a writer, and it is still the one most often needed \u2014 about characters, and about yourself.", source: "after Aristotle, Poetics VI" },
  { text: "Ask of each thing: is this according to nature, or only according to habit? Most of what you are carrying today is habit wearing the costume of necessity.", source: "in the manner of the Cynics" },
  { text: "The one who needs least is closest to the gods, who need nothing. Every possession is also a small piece of anxiety you have agreed to take on.", source: "in the manner of Diogenes" },
  { text: "Of everything wisdom gathers for a good life, the greatest by far is friendship. Not the largest house, not the safest position \u2014 the company of people who genuinely wish you well.", source: "after Epicurus, Principal Doctrines" },
  { text: "Sort your desires before you try to satisfy them. Some are natural and necessary, some natural but not necessary, and some neither. Almost all the misery is in the third group, and almost all the spending.", source: "after Epicurus, Letter to Menoeceus" },
  { text: "Death is not an event you will experience. While you exist it is not here, and when it arrives you are not. What you actually fear is not death but dying badly, or not having lived \u2014 and both of those are worth attending to today.", source: "after Epicurus, Letter to Menoeceus" },
  { text: "If you would not say it to his face, do not say it behind his back. If you would not want it done to you, do not do it to anyone else. The whole of the teaching hangs on one thread, and this is it.", source: "after Confucius, Analects XV" },
  { text: "Learning without thinking is wasted labour. Thinking without learning is dangerous. Most people are heavily out of balance in one direction and believe the problem is the other.", source: "after Confucius, Analects II" },
  { text: "When you know a thing, hold that you know it. When you do not know a thing, allow that you do not know it. This is what knowledge actually consists of, and almost nobody does it.", source: "after Confucius, Analects II" },
  { text: "The exemplary person is settled and does not fret; the small person frets and is never settled. Watch which one you were in the difficult conversation today.", source: "after Confucius, Analects VII" },
  { text: "Suppose you could make yourself invisible. Would you behave the same? Whatever changes in that thought experiment is the part of your character you have been renting rather than owning.", source: "after Plato, Republic II" },
  { text: "You cannot teach anyone anything. You can only ask the right question and stand back while they find it. Anyone who has ever watched a child work something out already knows this and forgets it the moment they start explaining.", source: "after Plato, Meno" },
  { text: "If you climbed out and saw the sun, and then went back down, you would be clumsy at the shadow game and they would say your eyes had been ruined. Expect this. It is not a reason not to climb out.", source: "after Plato, Republic VII" },
  { text: "Is it good because it is approved, or approved because it is good? Whichever way you answer, you have lost the ability to settle an argument by pointing at authority \u2014 and that is the honest position.", source: "after Plato, Euthyphro" },
  { text: "Beauty is a staircase, not a room. A face, then a character, then a just law, then the shape of things \u2014 each rung is real, and each one is only worth standing on until you can see the next.", source: "after Plato, Symposium" },
  { text: "What is time? If nobody asks, you know. The moment you try to explain it, you don't. Be a little slower today to assume that the things you use most fluently are the things you understand.", source: "after Augustine, Confessions XI" },
  { text: "Memory is a vast hall, and things come out of it unasked. When you go looking for one thing, a crowd of others rushes forward as if to say, perhaps it is us you want. Learn to brush them away without believing them.", source: "after Augustine, Confessions X" },
  { text: "Fortune's only consistency is that she turns. You climbed on knowing that. The complaint is not that she moved \u2014 it is that you had started to think the top of the wheel was a place you lived.", source: "after Boethius, The Consolation of Philosophy II" },
  { text: "We can more easily say what God is not than what God is. That discipline \u2014 describing by removing \u2014 is worth borrowing for anything genuinely large. You will be more accurate about it by subtraction than by decoration.", source: "after Thomas Aquinas, Summa Theologica I" },
  { text: "There is no knowledge harder to acquire than how to live this life well and naturally, and no sickness more barbarous than despising the fact of being alive at all.", source: "after Montaigne, Essays III" },
  { text: "Read to weigh and consider \u2014 not to contradict, not to believe, and not to have something to say at dinner. Some books deserve a taste, some a swallow, and two or three a lifetime of chewing.", source: "after Francis Bacon, Of Studies" },
  { text: "Almost all of it comes from being unable to sit quietly in a room alone. Try ten minutes of it today and watch how quickly you invent an errand.", source: "after Pascal, Pens\u00e9es" },
  { text: "You are the most fragile thing in the room and the only thing in it that knows so. A drop of water can end you and it will never know it did. That asymmetry is where your dignity actually lives.", source: "after Pascal, Pens\u00e9es 347" },
  { text: "Read the great books slowly and few at a time. Depth is not a quantity of pages. One book properly argued with will change more than fifty skimmed.", source: "in the manner of the liberal arts as a way of life" },
  { text: "Learn one thing by heart this week \u2014 a psalm, a stanza, a paragraph. Not to show anyone. A memorised thing is available in the dark, in hospital, on a bad night, when nothing you have bookmarked is.", source: "in the manner of the classical memory arts" },
];

window.VERSES = [
  { title: 'Invictus', text: 'Out of the night that covers me,\n  Black as the pit from pole to pole,\nI thank whatever gods may be\n  For my unconquerable soul.\n\nIt matters not how strait the gate,\n  How charged with punishments the scroll,\nI am the master of my fate,\n  I am the captain of my soul.', author: 'W. E. Henley (last two stanzas)', note: 'The Stoic creed in English. Learn the final quatrain first — it recites itself.' },
  { title: 'Ozymandias', text: 'I met a traveller from an antique land\nWho said: Two vast and trunkless legs of stone\nStand in the desert. Near them, on the sand,\nHalf sunk, a shattered visage lies...\nAnd on the pedestal these words appear:\n"My name is Ozymandias, king of kings:\nLook on my works, ye Mighty, and despair!"\nNothing beside remains.', author: 'Percy Bysshe Shelley', note: 'On the vanity of power — a memento mori in fourteen lines.' },
  { title: 'Psalm 23', text: 'The Lord is my shepherd; I shall not want.\nHe maketh me to lie down in green pastures:\nhe leadeth me beside the still waters.\nHe restoreth my soul.\nYea, though I walk through the valley of the shadow of death,\nI will fear no evil: for thou art with me.', author: 'King James Bible', note: 'The most-memorised passage in English. The cadence is half the meaning.' },
  { title: 'Sonnet 18', text: 'Shall I compare thee to a summer’s day?\nThou art more lovely and more temperate:\nRough winds do shake the darling buds of May,\nAnd summer’s lease hath all too short a date...\nSo long as men can breathe or eyes can see,\nSo long lives this, and this gives life to thee.', author: 'William Shakespeare', note: 'Learn the couplet, then work backwards. Poetry claiming to defeat death, and largely succeeding.' },
  { title: 'If—', text: 'If you can keep your head when all about you\n  Are losing theirs and blaming it on you...\nIf you can meet with Triumph and Disaster\n  And treat those two impostors just the same...\nYours is the Earth and everything that’s in it,\n  And—which is more—you’ll be a Man, my son!', author: 'Rudyard Kipling', note: 'A Victorian handbook of Stoic virtue. Long, but it builds in couplets that hold each other in place.' },
  { title: 'Carpe diem', text: 'Dum loquimur, fugerit invida\naetas: carpe diem, quam minimum credula postero.\n\n"While we speak, envious time will have fled: seize the day, trusting as little as possible in the next."', author: 'Horace, Odes I.11', note: 'The original. Learn the Latin line and its plain English together.' },
  { title: 'From "Ulysses"', text: 'Tho’ much is taken, much abides; and tho’\nWe are not now that strength which in old days\nMoved earth and heaven, that which we are, we are;\nOne equal temper of heroic hearts,\nMade weak by time and fate, but strong in will\nTo strive, to seek, to find, and not to yield.', author: 'Alfred, Lord Tennyson', note: 'The closing lines. On carrying on. The last line is the anchor.' },
  { title: 'A Stoic maxim', text: 'Memento mori.\n\n"Remember that you will die."\n\nMemento vivere.\n\n"Remember that you must live."', author: 'the Stoic tradition', note: 'Two words each. Hold them together — the first gives the second its urgency.' },
  { title: 'Sonnet 116', text: 'Let me not to the marriage of true minds\nAdmit impediments. Love is not love\nWhich alters when it alteration finds,\nOr bends with the remover to remove:\n\nO no! it is an ever-fixed mark\nThat looks on tempests and is never shaken.', author: 'Shakespeare, Sonnet 116 (opening)', note: 'Learn the first quatrain — the four rhymes lock it into memory fast.' },
  { title: 'This above all', text: 'This above all: to thine own self be true,\nAnd it must follow, as the night the day,\nThou canst not then be false to any man.', author: 'Shakespeare, Hamlet I.3 (Polonius’ counsel)', note: 'Three lines, one whole ethic. Say it once and it stays.' },
  { title: 'All the world’s a stage', text: 'All the world’s a stage,\nAnd all the men and women merely players;\nThey have their exits and their entrances,\nAnd one man in his time plays many parts.', author: 'Shakespeare, As You Like It II.7 (opening of the speech)', note: 'The famous four lines. Picture the stage and the words come back.' },
  { title: 'Psalm 1', text: 'Blessed is the man that walketh not in the counsel of the ungodly,\nnor standeth in the way of sinners…\n\nAnd he shall be like a tree planted by the rivers of water,\nthat bringeth forth his fruit in his season;\nhis leaf also shall not wither.', author: 'Psalm 1 (KJV)', note: 'The tree by the water is the anchor image — memorise the second stanza first.' },
  { title: 'Psalm 121', text: 'I will lift up mine eyes unto the hills,\nfrom whence cometh my help.\nMy help cometh from the LORD,\nwhich made heaven and earth.', author: 'Psalm 121 (KJV, opening)', note: 'A traveller’s psalm. Four lines that steady the mind on a hard road.' },
  { title: 'A time to every purpose', text: 'To every thing there is a season,\nand a time to every purpose under the heaven:\n\nA time to be born, and a time to die;\na time to plant, and a time to pluck up that which is planted.', author: 'Ecclesiastes 3 (KJV)', note: 'The parallel pairs carry themselves — say them in rhythm and they stick.' },
  { title: 'Charity', text: 'Though I speak with the tongues of men and of angels,\nand have not charity,\nI am become as sounding brass, or a tinkling cymbal.\n\nAnd now abideth faith, hope, charity, these three;\nbut the greatest of these is charity.', author: '1 Corinthians 13 (KJV)', note: 'Learn the last two lines first — they are the whole chapter in miniature.' },
  { title: 'A Psalm of Life', text: 'Tell me not, in mournful numbers,\n  Life is but an empty dream!—\nFor the soul is dead that slumbers,\n  And things are not what they seem.\n\nLife is real! Life is earnest!\n  And the grave is not its goal.', author: 'Longfellow, A Psalm of Life (opening stanzas)', note: '“Life is real! Life is earnest!” — the line that pulls the rest up with it.' },
  { title: 'Auguries of Innocence', text: 'To see a World in a Grain of Sand\nAnd a Heaven in a Wild Flower,\nHold Infinity in the palm of your hand\nAnd Eternity in an hour.', author: 'William Blake, Auguries of Innocence (opening)', note: 'Four lines, four images. Blake’s whole vision folds into them.' },
  { title: 'No man is an island', text: 'No man is an island, entire of itself;\nevery man is a piece of the continent, a part of the main.\n\nAny man’s death diminishes me,\nbecause I am involved in mankind;\nand therefore never send to know for whom the bell tolls;\nit tolls for thee.', author: 'John Donne, Meditation XVII', note: 'Prose that reads like verse. The last line is the hook — learn back from it.' },
  { title: 'Sapere aude', text: 'Dimidium facti qui coepit habet: sapere aude,\nincipe.\n\n"He who has begun is half done: dare to know — begin."', author: 'Horace, Epistles I.2', note: 'Learn the two Latin words and the plain English. A whole philosophy in one command: begin.' },
  { title: 'Audentes fortuna iuvat', text: 'Audentes fortuna iuvat.\n\n"Fortune favours the bold."', author: 'Virgil, Aeneid X.284', note: 'The shortest verse to carry. Say the Latin once and it is yours for life.' },
  { title: 'Labor omnia vincit', text: 'Labor omnia vincit\nimprobus.\n\n"Unremitting labour conquers all things."', author: 'Virgil, Georgics I.145–146', note: 'Two words hold the idea; the third makes it honest — the labour must be steady.' },
  { title: 'Know thyself', text: 'Γνῶθι σεαυτόν.\nGnōthi seauton.\n\n"Know thyself."\n\nΜηδὲν ἄγαν.\nMēden agan.\n\n"Nothing in excess."', author: 'The Delphic maxims (inscribed at the Temple of Apollo)', note: 'Two ancient commands carved in stone. Learn the transliterations aloud and the Greek follows.' },
  { title: 'The Road Not Taken', text: 'Two roads diverged in a yellow wood,\nAnd sorry I could not travel both\nAnd be one traveler, long I stood\nAnd looked down one as far as I could\nTo where it bent in the undergrowth.', author: 'Robert Frost, The Road Not Taken (opening stanza, 1916)', note: 'The first stanza sets the whole scene — learn it and the fork is always with you.' },
  { title: 'Hope is the thing with feathers', text: '“Hope” is the thing with feathers -\nThat perches in the soul -\nAnd sings the tune without the words -\nAnd never stops - at all -', author: 'Emily Dickinson, Poem 314 (opening stanza)', note: 'One small image of a bird that never stops singing. The dashes are hers — keep them.' },
  { title: 'On His Blindness', text: 'When I consider how my light is spent,\n  Ere half my days, in this dark world and wide…\n\n"They also serve who only stand and wait."', author: 'Milton, Sonnet 19 (opening and close)', note: 'The last line is the whole comfort — patience is also service. Learn it first.' },
  { title: 'Ode on a Grecian Urn', text: '"Beauty is truth, truth beauty," — that is all\nYe know on earth, and all ye need to know.', author: 'Keats, Ode on a Grecian Urn (closing lines)', note: 'The final couplet of the ode. Two lines that have outlasted the urn itself.' },
  { title: 'The Character of a Happy Life', text: 'How happy is he born and taught\nThat serveth not another’s will;\nWhose armour is his honest thought,\nAnd simple truth his utmost skill!', author: 'Sir Henry Wotton, The Character of a Happy Life (opening stanza)', note: 'A Stoic portrait in plain rhyme. The honest thought as armour is the line to hold.' },
  { title: 'Virtue', text: 'Sweet day, so cool, so calm, so bright,\nThe bridal of the earth and sky;\nThe dew shall weep thy fall to-night;\n  For thou must die.', author: 'George Herbert, Virtue (opening stanza)', note: 'Memento mori made gentle. The short last line lands the whole thought.' },
  { title: 'Non omnis moriar', text: 'Exegi monumentum aere perennius…\nnon omnis moriar.\n\n"I have built a monument more lasting than bronze… I shall not wholly die."', author: 'Horace, Odes III.30', note: 'The poet’s wager against time. Learn “non omnis moriar” — three words, one defiance.' },
  { title: 'The quality of mercy', text: 'The quality of mercy is not strain’d,\nIt droppeth as the gentle rain from heaven\nUpon the place beneath. It is twice blest;\nIt blesseth him that gives and him that takes.', author: 'Shakespeare, The Merchant of Venice IV.1 (Portia’s speech)', note: 'The rain image opens it; “twice blest” is the heart. Learn those two beats and it flows.' },
  { title: "The Tyger", text: "Tyger Tyger, burning bright,\nIn the forests of the night;\nWhat immortal hand or eye,\nCould frame thy fearful symmetry?", author: "William Blake, Songs of Experience (1794)", note: "Every line is a question and none of them is answered. Say it aloud and you will hear the hammer in it." },
  { title: "And did those feet", text: "And did those feet in ancient time\nWalk upon England's mountains green:\nAnd was the holy Lamb of God,\nOn England's pleasant pastures seen!\n\nI will not cease from Mental Fight,\nNor shall my Sword sleep in my hand:\nTill we have built Jerusalem,\nIn England's green & pleasant Land.", author: "William Blake, preface to Milton (1810)", note: "Four questions, then a vow. The vow is the part worth carrying." },
  { title: "The world is too much with us", text: "The world is too much with us; late and soon,\nGetting and spending, we lay waste our powers;\nLittle we see in Nature that is ours;\nWe have given our hearts away, a sordid boon!", author: "William Wordsworth (1807)", note: "Written before electric light, let alone anything else. The complaint has not aged a day." },
  { title: "I wandered lonely as a cloud", text: "I wandered lonely as a cloud\nThat floats on high o'er vales and hills,\nWhen all at once I saw a crowd,\nA host, of golden daffodils...\n\nFor oft, when on my couch I lie\nIn vacant or in pensive mood,\nThey flash upon that inward eye\nWhich is the bliss of solitude.", author: "William Wordsworth (1807)", note: "The famous part is the flowers. The real part is the last stanza \u2014 that the sight kept paying out for years." },
  { title: "She Walks in Beauty", text: "She walks in beauty, like the night\nOf cloudless climes and starry skies;\nAnd all that's best of dark and bright\nMeet in her aspect and her eyes.", author: "Lord Byron (1814)", note: "Six syllables to the line and not one wasted." },
  { title: "To Autumn", text: "Season of mists and mellow fruitfulness,\nClose bosom-friend of the maturing sun;\nConspiring with him how to load and bless\nWith fruit the vines that round the thatch-eves run.", author: "John Keats (1819)", note: "Keats had a year to live when he wrote it. There is no grief anywhere in it." },
  { title: "Bright star", text: "Bright star, would I were stedfast as thou art \u2014\nNot in lone splendour hung aloft the night\nAnd watching, with eternal lids apart,\nLike nature's patient, sleepless Eremite.", author: "John Keats (1819)", note: "Written in English, so the old words are his own. He wanted the constancy, not the loneliness." },
  { title: "To a Skylark", text: "Hail to thee, blithe Spirit!\n  Bird thou never wert,\nThat from Heaven, or near it,\n  Pourest thy full heart\nIn profuse strains of unpremeditated art.", author: "Percy Bysshe Shelley (1820)", note: "'Unpremeditated art' is the whole ambition of the Romantics in two words." },
  { title: "To a Mouse", text: "But Mousie, thou art no thy lane,\nIn proving foresight may be vain:\nThe best-laid schemes o' Mice an' Men\n  Gang aft agley,\nAn' lea'e us nought but grief an' pain,\n  For promis'd joy!", author: "Robert Burns (1785)", note: "He turned up a mouse's nest with a plough and wrote it the same day." },
  { title: "Elegy in a Country Churchyard", text: "The boast of heraldry, the pomp of pow'r,\n  And all that beauty, all that wealth e'er gave,\nAwaits alike th' inevitable hour.\n  The paths of glory lead but to the grave.", author: "Thomas Gray (1751)", note: "Gray worked on it for eight years. It shows, in the best way." },
  { title: "To His Coy Mistress", text: "Had we but world enough and time,\nThis coyness, Lady, were no crime...\nBut at my back I always hear\nTime's wing\u00e8d chariot hurrying near;\nAnd yonder all before us lie\nDeserts of vast eternity.", author: "Andrew Marvell (c. 1650)", note: "A seduction poem that turns, halfway, into the best memento mori in English." },
  { title: "To the Virgins", text: "Gather ye rosebuds while ye may,\n  Old Time is still a-flying:\nAnd this same flower that smiles to-day,\n  To-morrow will be dying.", author: "Robert Herrick (1648)", note: "Horace's carpe diem, three hundred years later, in a language that had caught up with it." },
  { title: "To Althea, from Prison", text: "Stone walls do not a prison make,\n  Nor iron bars a cage;\nMinds innocent and quiet take\n  That for an hermitage.", author: "Richard Lovelace (1642)", note: "He was in prison when he wrote it, which is the only thing that gives a line like that any authority." },
  { title: "Death, be not proud", text: "Death, be not proud, though some have called thee\nMighty and dreadful, for thou art not so...\nOne short sleep past, we wake eternally,\nAnd death shall be no more; Death, thou shalt die.", author: "John Donne, Holy Sonnet X", note: "Written in English \u2014 the old words are Donne's own. Note that he argues with death rather than mourning." },
  { title: "The Pulley", text: "When God at first made man,\nHaving a glasse of blessings standing by;\nLet us (said he) poure on him all we can:\nLet the worlds riches, which dispersed lie,\nContract into a span.", author: "George Herbert (1633)", note: "God keeps back rest, so that restlessness will drive us home. The same idea as Augustine's restless heart, in twenty lines." },
  { title: "They are all gone into the world of light", text: "They are all gone into the world of light!\n  And I alone sit ling'ring here;\nTheir very memory is fair and bright,\n  And my sad thoughts doth clear.", author: "Henry Vaughan (1655)", note: "One of the plainest poems of grief in the language." },
  { title: "Of Man's first disobedience", text: "Of Man's first disobedience, and the fruit\nOf that forbidden tree whose mortal taste\nBrought death into the World, and all our woe...\nSing, Heavenly Muse.", author: "John Milton, Paradise Lost I (1667)", note: "Milton is deliberately doing what Homer and Virgil did \u2014 and in English, so the grandeur is his own choice, not a translator's." },
  { title: "Sonnet 29", text: "When, in disgrace with fortune and men's eyes,\nI all alone beweep my outcast state...\nYet in these thoughts myself almost despising,\nHaply I think on thee, and then my state,\nLike to the lark at break of day arising\nFrom sullen earth, sings hymns at heaven's gate.", author: "William Shakespeare", note: "The turn comes exactly where the sonnet form says it should, and it still surprises you." },
  { title: "Our revels now are ended", text: "Our revels now are ended. These our actors,\nAs I foretold you, were all spirits and\nAre melted into air, into thin air...\nWe are such stuff\nAs dreams are made on, and our little life\nIs rounded with a sleep.", author: "Shakespeare, The Tempest IV.1", note: "Probably the last speech he wrote alone, and he gave it to a man breaking his own staff." },
  { title: "Pied Beauty", text: "Glory be to God for dappled things \u2014\n  For skies of couple-colour as a brinded cow;\n    For rose-moles all in stipple upon trout that swim...\nAll things counter, original, spare, strange;\n  Whatever is fickle, freckled (who knows how?)\n    He fathers-forth whose beauty is past change:\n      Praise him.", author: "Gerard Manley Hopkins (1877)", note: "Hopkins invented his own metre because the existing ones could not do this." },
  { title: "Loveliest of trees", text: "Loveliest of trees, the cherry now\nIs hung with bloom along the bough...\nAnd since to look at things in bloom\nFifty springs are little room,\nAbout the woodlands I will go\nTo see the cherry hung with snow.", author: "A. E. Housman, A Shropshire Lad (1896)", note: "He does the arithmetic on his own life in the second stanza and then goes outside." },
  { title: "Remember", text: "Remember me when I am gone away,\n  Gone far away into the silent land...\nYet if you should forget me for a while\n  And afterwards remember, do not grieve:\nFor if the darkness and corruption leave\n  A vestige of the thoughts that once I had,\nBetter by far you should forget and smile\n  Than that you should remember and be sad.", author: "Christina Rossetti (1862)", note: "It sets out to ask to be remembered and changes its mind." },
  { title: "No coward soul is mine", text: "No coward soul is mine,\nNo trembler in the world's storm-troubled sphere:\nI see Heaven's glories shine,\nAnd faith shines equal, arming me from fear.", author: "Emily Bront\u00eb (1846)", note: "Said to be the last thing she wrote." },
  { title: "Because I could not stop for Death", text: "Because I could not stop for Death \u2014\nHe kindly stopped for me \u2014\nThe Carriage held but just Ourselves \u2014\nAnd Immortality.", author: "Emily Dickinson", note: "Death as a courteous gentleman caller. Nobody had done that before." },
  { title: "O Me! O Life!", text: "O me! O life! of the questions of these recurring...\nWhat good amid these, O me, O life?\n\nAnswer.\nThat you are here \u2014 that life exists and identity,\nThat the powerful play goes on, and you may contribute a verse.", author: "Walt Whitman (1892)", note: "The question takes twenty lines and the answer takes four." },
  { title: "The Lake Isle of Innisfree", text: "I will arise and go now, and go to Innisfree,\nAnd a small cabin build there, of clay and wattles made...\nAnd I shall have some peace there, for peace comes dropping slow,\nDropping from the veils of the morning to where the cricket sings.", author: "W. B. Yeats (1890)", note: "He wrote it in London, homesick, after hearing a shop fountain." },
  { title: "Stopping by Woods on a Snowy Evening", text: "The woods are lovely, dark and deep,\nBut I have promises to keep,\nAnd miles to go before I sleep,\nAnd miles to go before I sleep.", author: "Robert Frost (1923)", note: "The repeated last line is doing two different jobs, and Frost refused all his life to say what they were." },
  { title: "Requiem", text: "Under the wide and starry sky,\nDig the grave and let me lie.\nGlad did I live and gladly die,\n  And I laid me down with a will.\n\nThis be the verse you grave for me:\nHere he lies where he longed to be.", author: "Robert Louis Stevenson (1887)", note: "It is carved on his grave in Samoa, which he chose." },
  { title: "Dover Beach", text: "Ah, love, let us be true\nTo one another! for the world, which seems\nTo lie before us like a land of dreams,\nSo various, so beautiful, so new,\nHath really neither joy, nor love, nor light,\nNor certitude, nor peace, nor help for pain.", author: "Matthew Arnold (1867)", note: "The bleakest lines in Victorian poetry, and the answer he gives is a person, not an argument." },
  { title: "Dulce et Decorum Est", text: "If in some smothering dreams you too could pace\nBehind the wagon that we flung him in...\nMy friend, you would not tell with such high zest\nTo children ardent for some desperate glory,\nThe old Lie: Dulce et decorum est\nPro patria mori.", author: "Wilfred Owen (1918)", note: "Owen is answering Horace directly, by name. Read it next to the Horace odes elsewhere in this app \u2014 that argument is the whole of the twentieth century." },
  { title: "The Soldier", text: "If I should die, think only this of me:\n  That there's some corner of a foreign field\nThat is for ever England.", author: "Rupert Brooke (1914)", note: "Written in the first months, before anyone knew. Brooke died the following April." },
  { title: "Recessional", text: "Far-called, our navies melt away;\n  On dune and headland sinks the fire:\nLo, all our pomp of yesterday\n  Is one with Nineveh and Tyre!\nJudge of the Nations, spare us yet,\nLest we forget \u2014 lest we forget!", author: "Rudyard Kipling (1897)", note: "Written for the Diamond Jubilee, at the height of the empire, and it is a warning." },
  { title: "Psalm 90", text: "Lord, thou hast been our dwelling place in all generations...\nFor a thousand years in thy sight are but as yesterday when it is past,\nand as a watch in the night.\n\nSo teach us to number our days,\nthat we may apply our hearts unto wisdom.", author: "Psalm 90 (KJV)", note: "Written in English by the King James translators, so the old words stay. 'Number our days' is the oldest memento mori in the book." },
  { title: "Proverbs 3", text: "Trust in the Lord with all thine heart;\nand lean not unto thine own understanding.\nIn all thy ways acknowledge him,\nand he shall direct thy paths.", author: "Proverbs 3:5\u20136 (KJV)", note: "Four lines that have been memorised more often than almost anything else in English." },
  { title: "Ecclesiastes 9", text: "Whatsoever thy hand findeth to do, do it with thy might;\nfor there is no work, nor device, nor knowledge, nor wisdom,\nin the grave, whither thou goest.", author: "Ecclesiastes 9:10 (KJV)", note: "The bleakest book in the Bible arrives, in the end, at: get on with it." },
  { title: "Ecclesiastes 12", text: "Remember now thy Creator in the days of thy youth,\nwhile the evil days come not,\nnor the years draw nigh, when thou shalt say,\nI have no pleasure in them.", author: "Ecclesiastes 12:1 (KJV)", note: "The chapter that follows is the finest description of growing old in any language." },
  { title: "Job 38", text: "Where wast thou when I laid the foundations of the earth?\ndeclare, if thou hast understanding...\nWhen the morning stars sang together,\nand all the sons of God shouted for joy?", author: "Job 38 (KJV)", note: "God's answer to Job is not an answer. It is seventy lines of questions, and it works." },
  { title: "Isaiah 40", text: "They that wait upon the Lord shall renew their strength;\nthey shall mount up with wings as eagles;\nthey shall run, and not be weary;\nand they shall walk, and not faint.", author: "Isaiah 40:31 (KJV)", note: "Note the order \u2014 fly, run, walk. It descends, and the walking is the hardest." },
  { title: "Like the generations of leaves", text: "Like the generations of leaves are those of men.\nThe wind blows and one year's leaves are scattered on the ground,\nbut the trees bud and fresh leaves open when spring comes again.\nSo a generation of men is born as another passes away.", author: "Homer, Iliad VI (Kline trans.)", note: "Spoken by one soldier to another in the moment before they were going to fight. They did not fight." },
  { title: "Nothing more wonderful than man", text: "There are many strange and wonderful things,\nbut nothing more strangely wonderful than man.\nHe moves across the white-capped ocean seas\nblasted by winter storms, carving his way\nunder the surging waves engulfing him.", author: "Sophocles, Antigone (Johnston trans.)", note: "A modern translation, so it reads as directly as it did in the theatre. The chorus is not entirely admiring." },
];

window.PASSAGES = [
  { title: 'The Allegory of the Cave', source: 'Plato, Republic VII (Jowett trans.)', text: 'And now, I said, let me show in a figure how far our nature is enlightened or unenlightened: Behold! human beings living in an underground den, which has a mouth open towards the light and reaching all along the den; here they have been from their childhood, and have their legs and necks chained so that they cannot move, and can only see before them, being prevented by the chains from turning round their heads. Above and behind them a fire is blazing at a distance, and between the fire and the prisoners there is a raised way; and you will see, if you look, a low wall built along the way, like the screen which marionette players have in front of them, over which they show the puppets.\n\nAnd do you see, I said, men passing along the wall carrying all sorts of vessels, and statues and figures of animals made of wood and stone and various materials, which appear over the wall? Some of them are talking, others silent.\n\nYou have shown me a strange image, and they are strange prisoners.\n\nLike ourselves, I replied; and they see only their own shadows, or the shadows of one another, which the fire throws on the opposite wall of the cave.' },
  { title: 'On beginning the day', source: 'Marcus Aurelius, Meditations V.1', text: 'In the morning when you rise unwillingly, let this thought be present: I am rising to the work of a human being. Why then am I dissatisfied if I am going to do the things for which I exist and for which I was brought into the world? Or have I been made for this, to lie under the blankets and keep myself warm?\n\nBut this is more pleasant. Do you exist then to take your pleasure, and not at all for action or exertion? Do you not see the little plants, the little birds, the ants, the spiders, the bees working together to put in order their several parts of the universe? And are you unwilling to do the work of a human being, and do you not make haste to do that which is according to your nature?' },
  { title: 'On what is in our power', source: 'Epictetus, Enchiridion I', text: 'Of things some are in our power, and others are not. In our power are opinion, movement towards a thing, desire, aversion; and in a word, whatever are our own acts. Not in our power are the body, property, reputation, offices, and in a word, whatever are not our own acts.\n\nThe things in our power are by nature free, not subject to restraint or hindrance: but the things not in our power are weak, slavish, subject to restraint, in the power of others. Remember then, that if you think the things which are by nature slavish to be free, and the things which are in the power of others to be your own, you will be hindered, you will lament, you will be disturbed, you will blame both gods and men.' },
  { title: 'That virtue comes by habit', source: 'Aristotle, Nicomachean Ethics II.1', text: 'Virtue, then, being of two kinds, intellectual and moral, intellectual virtue in the main owes both its birth and its growth to teaching (for which reason it requires experience and time), while moral virtue comes about as a result of habit.\n\nFrom this it is plain that none of the moral virtues arises in us by nature; for nothing that exists by nature can form a habit contrary to its nature. The virtues we get by first exercising them, as also happens in the case of the arts. For the things we have to learn before we can do them, we learn by doing them; men become builders by building and lyre-players by playing the lyre; so too we become just by doing just acts, temperate by doing temperate acts, brave by doing brave acts.' },
  { title: 'On the shortness of life', source: 'Seneca, De Brevitate Vitae', text: 'It is not that we have a short time to live, but that we waste a lot of it. Life is long enough, and a sufficiently generous amount has been given to us for the highest achievements if it were all well invested. But when it is wasted in heedless luxury and spent on no good activity, we are forced at last by death’s final constraint to realise that it has passed away before we knew it was passing.\n\nSo it is: we are not given a short life but we make it short, and we are not ill-supplied but wasteful of it. Life is long if you know how to use it.' },
  { title: 'The end of all our exploring', source: 'Boethius, The Consolation of Philosophy (Book II)', text: 'Nothing is miserable unless you think it so; and on the other hand, nothing brings happiness unless you are content with it. If, then, no one is content with his lot, however fortunate, and each man finds some cause for complaint, does this not show that they who possess it are unhappy? You look for a firm foundation, and you build upon shifting sand.\n\nWhy then do mortal men seek after happiness outside themselves, when it lies within? You are confounded by error and ignorance. I will show you, in brief, the pattern of the highest happiness: is there anything more precious to you than yourself? Nothing, you will say. Then, if you are master of yourself, you will possess what you will never wish to lose, and what fortune cannot take from you.' },
  { title: 'The soul and the harmony of the lyre', source: 'Plato, Phaedo (Jowett trans.)', text: 'Suppose a person to use the same argument about harmony and the lyre — might he not say that harmony is a thing invisible, incorporeal, perfectly beautiful and divine in the well-attuned lyre, but that the lyre and the strings are matter and material, composite, earthy, and akin to mortality?\n\nAnd when someone breaks the lyre, or cuts and rends the strings, then he who takes this view would argue as you do, and on the same analogy, that the harmony survives and has not perished; for you cannot imagine, as we would say, that the lyre without the strings, and the broken strings themselves, remain, and yet that the harmony, which is of heavenly and immortal nature, has perished before the mortal.\n\nThe harmony must still be somewhere, and the wood and strings will decay before anything can happen to it.' },
  { title: 'The ladder of love', source: 'Plato, Symposium (Jowett trans.)', text: 'For he who would proceed aright in this matter should begin in youth to visit beautiful forms; and first, if he be guided by his instructor aright, to love one such form only — out of that he should create fair thoughts; and soon he will of himself perceive that the beauty of one form is akin to the beauty of another.\n\nAnd when he perceives this he will abate his violent love of the one, which he will despise and deem a small thing, and will become a lover of all beautiful forms; in the next stage he will consider that the beauty of the mind is more honourable than the beauty of the outward form.\n\nHe who has been instructed thus far in the things of love, and who has learned to see the beautiful in due order and succession, when he comes toward the end will suddenly perceive a nature of wondrous beauty — a beauty everlasting, not growing and decaying.' },
  { title: 'I am the gadfly', source: 'Plato, Apology (Jowett trans.)', text: 'For if you kill me you will not easily find another like me, who, if I may use such a ludicrous figure of speech, am a sort of gadfly, given to the state by God; and the state is like a great and noble steed who is tardy in his motions owing to his very size, and requires to be stirred into life.\n\nI am that gadfly which God has given to the state, and all day long and in all places am always fastening upon you, arousing and persuading and reproaching you. And as you will not easily find another like me, I would advise you to spare me.\n\nFor I do nothing but go about persuading you all, old and young alike, not to take thought for your persons and your properties, but first and chiefly to care about the greatest improvement of the soul.' },
  { title: 'The charioteer of the soul', source: 'Plato, Phaedrus (Jowett trans.)', text: 'Let the figure be composite — a pair of winged horses and a charioteer. Now the winged horses and the charioteers of the gods are all of them noble and of noble descent, but those of other races are mixed; the human charioteer drives his in a pair; and one of them is noble and of noble breed, and the other is ignoble and of ignoble breed; and the driving of them of necessity gives a great deal of trouble to him.\n\nThe wing is intended to soar aloft and carry that which gravitates downwards into the upper region, which is the habitation of the gods. The divine is beauty, wisdom, goodness, and the like; and by these the wing of the soul is nourished, and grows apace.\n\nBut when fed upon evil and foulness and the opposite of good, the wing wastes and falls away.' },
  { title: 'The life of contemplation', source: 'Aristotle, Nicomachean Ethics X (Ross trans.)', text: 'If happiness is activity in accordance with virtue, it is reasonable that it should be in accordance with the highest virtue; and this will be that of the best thing in us. This activity is contemplative.\n\nThat this activity is contemplative and aims at no end beyond itself, and that it has its pleasure proper to itself, and its self-sufficiency and leisureliness, and all the other attributes ascribed to the supremely happy man — these evidently are those connected with this activity.\n\nBut such a life would be too high for man; for it is not in so far as he is man that he will live so, but in so far as something divine is present in him. We must not follow those who advise us, being men, to think of human things, and, being mortal, of mortal things, but must, so far as we can, make ourselves immortal, and strain every nerve to live in accordance with the best thing in us.' },
  { title: 'Friendship and the good', source: 'Aristotle, Nicomachean Ethics VIII (Ross trans.)', text: 'Friendship is a virtue or implies virtue, and is besides most necessary with a view to living. For without friends no one would choose to live, though he had all other goods; even rich men and those in possession of office and of dominion are thought to need friends most of all.\n\nPerfect friendship is the friendship of men who are good, and alike in virtue; for these wish well alike to each other qua good, and they are good in themselves. Now those who wish well to their friends for their sake are most truly friends; for they do this by reason of their own nature and not incidentally.\n\nSuch friendship is permanent, and it is what good men have; for each is good without qualification and also useful to his friend. And each is good, and good for his friend.' },
  { title: "The retreat into yourself", source: "Marcus Aurelius, Meditations IV.3 (Farquharson trans.)", text: "Men look for retreats for themselves, the country, the sea-shore, the hills; and you yourself, too, are peculiarly accustomed to feel the same want. Yet all this is very unlike a philosopher, when you may at any hour you please retreat into yourself.\n\nFor nowhere does a man retreat into more quiet or more privacy than into his own mind, especially one who has within such things that he has only to look into, and become at once in perfect ease; and by ease I mean nothing else but good behaviour.\n\nContinually, therefore, grant yourself this retreat and repair yourself. But let them be brief and fundamental truths, which will suffice at once by their presence to wash away all sorrow, and to send you back without repugnance to the life to which you return." },
  { title: "What, then, can guide a man?", source: "Marcus Aurelius, Meditations II.17 (Farquharson trans.)", text: "Briefly, all the things of the body are a river; all the things of the spirit, dream and delirium; his life a warfare and a sojourn in a strange land, his after-fame oblivion.\n\nWhat then can be his escort through life? One thing and one thing only \u2014 philosophy. And this is to keep the spirit within him unwronged and unscathed, master of pains and pleasures, doing nothing at random, nothing falsely and with pretence; and moreover accepting what befalls it, that is, what is assigned to it, as coming from that other world from which it came itself.\n\nAnd in all things awaiting death with a mind that is satisfied, counting it nothing else than a release of the elements from which each living creature is composed." },
  { title: 'On the good use of time', source: 'Seneca, Letters to Lucilius I (Gummere trans.)', text: 'Continue to act thus, my dear Lucilius — set yourself free for your own sake; gather and save your time, which till lately has been forced from you, or filched away, or has merely slipped from your hands.\n\nMake yourself believe the truth of my words — that certain moments are torn from us, that some are gently removed, and that others glide beyond our reach. The most disgraceful kind of loss, however, is that due to carelessness. Furthermore, if you will pay close heed to the problem, you will find that the largest portion of our life passes while we are doing ill, a goodly share while we are doing nothing, and the whole while we are doing that which is not to the purpose.\n\nHold every hour in your grasp. Lay hold of to-day’s task, and you will not need to depend so much upon to-morrow’s. While we are postponing, life speeds by.' },
  { title: 'On true friendship', source: 'Seneca, Letters to Lucilius III (Gummere trans.)', text: 'After friendship is formed you must trust, but before that you must judge. Those persons indeed put last first and confound their duties, who, violating the rules of Theophrastus, judge a man after they have made him their friend, instead of making him their friend after they have judged him.\n\nPonder for a long time whether you shall admit a given person to your friendship; but when you have decided to admit him, welcome him with all your heart and soul. Speak as boldly with him as with yourself.\n\nRegard him as loyal, and you will make him loyal. When the friendship is settled, ponder each situation with a friend; but ponder first about the friend himself. It is equally faulty to trust everyone and to trust no one.' },
  { title: 'That death is nothing to us', source: 'Epicurus, Letter to Menoeceus (Bailey trans.)', text: 'Accustom thyself to believe that death is nothing to us, for good and evil imply the capacity for sensation, and death is the privation of all sentience; therefore a correct understanding that death is nothing to us makes the mortality of life enjoyable, not because it adds to it an infinite span of time, but because it takes away the craving for immortality.\n\nFor life has no terrors for him who has thoroughly apprehended that there are no terrors for him in ceasing to live. So death, the most terrifying of ills, is nothing to us, since so long as we exist death is not with us; but when death comes, then we do not exist.\n\nIt does not concern either the living or the dead, since for the former it is not, and the latter are no more.' },
  { title: 'The serenity of old age', source: 'Cicero, On Old Age (Shuckburgh trans.)', text: 'The arms best suited to old age are the attainment and practice of the virtues, which, if cultivated in every period of life, produce wonderful fruits at the close of a long and busy career — not only because they never leave a man, not even at the very end of life, although that is a most important consideration, but also because the consciousness of a well-spent life and the recollection of many virtuous actions are exceedingly delightful.\n\nOld men retain their intellects well enough, if only they keep their minds active and fully employed. Nor is that the case only with men of high position and great office; it applies equally to private life and peaceful pursuits.\n\nWhat is more charming than an old age surrounded by the enthusiasm of youth? For the fruits of study in an honourable life are most delightful.' },
  { title: 'The Dream of Scipio', source: 'Cicero, On the Republic VI (Keyes trans.)', text: 'Be assured of this, so that you may be even more eager to defend the commonwealth: all those who have preserved, aided, or enlarged their fatherland have a special place prepared for them in the heavens, where they may enjoy an eternal life of happiness. For nothing of all that is done on earth is more pleasing to that supreme God who rules the whole universe than the assemblies and gatherings of men associated in justice, which are called states.\n\nStrive on indeed, and be sure that it is not you that is mortal, but only your body. For that man whom your outward form reveals is not yourself; the spirit is the true self, not that physical figure which can be pointed out by the finger.\n\nKnow, then, that you are a god, if a god is that which lives, feels, remembers, and foresees.' },
  { title: "The generative power of nature", source: "Lucretius, On the Nature of Things I (Kelk trans.)", text: "O mother of Aeneas' children, who\nDelight both men and gods, dear Venus, you\nWho fill with fruitfulness the busy sea\nAnd teeming lands beneath the canopy\nOf gliding stars, all creatures are created\nThrough you, through you we are illuminated\nBy the sun: the winds and clouds all flee away\nAt your approach, for you a rich display\nThroughout the beautiful and chequered earth\nOf flowers is seen, the seas betray their mirth,\nFor you the radiant land spreads out its light." },
  { title: "Our heart is restless", source: "Augustine, Confessions I.1 (rendered in plain modern English from the Latin)", text: "You are great, Lord, and greatly to be praised. Your power is great, and your wisdom has no limit. And a human being wants to praise you \u2014 one small piece of what you have made, carrying his own mortality about with him, carrying the evidence of his own wrongdoing and the evidence that you resist the proud. Still he wants to praise you, this small piece of your creation.\n\nYou stir him to take pleasure in praising you, because you made us for yourself, and our heart is restless until it rests in you.\n\nGrant me to know and understand which comes first \u2014 to call on you, or to praise you; and whether knowing you comes before calling on you. For who can call on you without knowing you?" },
  { title: "The music of number", source: "Boethius, The Consolation of Philosophy III, poem 9 (rendered in plain modern English from the Latin)", text: "You who govern the world by a reason that never ends, sower of earth and sky, who bid time move from what has no time \u2014 yourself unmoving, and setting all else in motion. No outside force drove you to shape this work out of matter without form, only the idea of the good, held within you and free of envy.\n\nYou hold the elements in proportion, so that cold agrees with heat and wet with dry, so that fire, the purer part, does not fly off, and weight does not drag the earth down under.\n\nYou bind the moving soul by number, dividing it so that it gathers its motion into two circles, and turns back upon itself, and circles the deep mind, and turns the heavens on the same pattern." },
  { title: 'The gathered sayings of the Master', source: 'Confucius, Analects (Legge trans.)', text: 'The Master said, Is it not pleasant to learn with a constant perseverance and application? Is it not delightful to have friends coming from distant quarters? Is he not a man of complete virtue, who feels no discomposure though men may take no note of him?\n\nThe Master said, Learning without thought is labour lost; thought without learning is perilous.\n\nThe Master said, When you know a thing, to hold that you know it; and when you do not know a thing, to allow that you do not know it — this is knowledge.\n\nThe Master said, The wise find pleasure in water; the virtuous find pleasure in hills. The wise are active; the virtuous are tranquil. The wise are joyful; the virtuous are long-lived.\n\nThe Master said, At fifteen, I had my mind bent on learning. At thirty, I stood firm. At forty, I had no doubts.' },
  { title: "The parting of Hector and Andromache", source: "Homer, Iliad VI (Kline trans.)", text: "With this, glorious Hector held out his arms to take his son, but the child, alarmed at sight of his father, shrank back with a cry on his fair nurse's breast, fearing the helmet's bronze and the horsehair crest nodding darkly at him.\n\nHis father and mother smiled, and glorious Hector doffed the shining helmet at once and laid it on the ground. Then he kissed his beloved son, dandled him in his arms, and prayed aloud: \u201cZeus, and all you gods, grant that this boy like me may be foremost among the Trojans, as mighty in strength, and a powerful leader of Ilium. And some day may they say of him, as he returns from war, \u2018He\u2019s a better man than his father\u2019.\u201d\n\nWith this he placed the child in his dear wife's arms, and she took him to her fragrant breast, smiling through her tears." },
  { title: 'The song of the returning wanderer', source: 'Homer, Odyssey V (Butler trans.)', text: 'So here Ulysses toiled, till the dawn should come. It was fortunate for him that the sea had driven him on to a part of the shore which was smooth and even, out of reach of the breakers, and he found a place where two thickets met.\n\nHe crept beneath them, and heaped up a bed of leaves, for there was such a store of them that two or three men might have slept there even in hard winter weather. This sight Ulysses was glad enough to see, so he lay down and heaped the leaves all round him.\n\nAs one who lives on a lonely farm and has no neighbours, cares for the seed of fire as a precious thing beneath the ashes, that he may not have to seek it elsewhere — even so did Ulysses cover himself over with leaves; and Minerva shed a sweet sleep upon his eyes.' },
  { title: 'Trust thyself', source: 'Ralph Waldo Emerson, Self-Reliance', text: 'There is a time in every man’s education when he arrives at the conviction that envy is ignorance; that imitation is suicide; that he must take himself for better, for worse, as his portion; that though the wide universe is full of good, no kernel of nourishing corn can come to him but through his toil bestowed on that plot of ground which is given to him to till.\n\nThe power which resides in him is new in nature, and none but he knows what that is which he can do, nor does he know until he has tried.\n\nTrust thyself: every heart vibrates to that iron string. Accept the place the divine providence has found for you, the society of your contemporaries, the connection of events. Great men have always done so, and confided themselves childlike to the genius of their age.' },
  { title: "The anger of Achilles", source: "Homer, Iliad I (Kline trans.)", text: "Goddess, sing me the anger, of Achilles, Peleus' son, that fatal anger that brought countless sorrows on the Greeks, and sent many valiant souls of warriors down to Hades, leaving their bodies as spoil for dogs and carrion birds: for thus was the will of Zeus brought to fulfilment.\n\nSing of it from the moment when Agamemnon, Atreus' son, that king of men, parted in wrath from noble Achilles.\n\nThe oldest poem in Europe opens not with a war or a hero but with a mood \u2014 one man's rage, and everything it costs everyone else." },
  { title: "Like the generations of leaves", source: "Homer, Iliad VI (Kline trans.)", text: "'Brave Diomedes', Hippolochus' son replied, 'why ask my lineage? Like the generations of leaves are those of men. The wind blows and one year's leaves are scattered on the ground, but the trees bud and fresh leaves open when spring comes again. So a generation of men is born as another passes away.'\n\nTwo men meet on a battlefield to kill each other, and one of them stops to say this. It is the oldest surviving statement in European literature of what a human life is measured against.\n\nThey discover their grandfathers were friends, exchange armour, and refuse to fight." },
  { title: "I sing of arms and the man", source: "Virgil, Aeneid I (Kline trans.)", text: "I sing of arms and the man, he who, exiled by fate, first came from the coast of Troy to Italy, and to Lavinian shores \u2014 hurled about endlessly by land and sea, by the will of the gods, by cruel Juno's remorseless anger, long suffering also in war, until he founded a city and brought his gods to Latium: from that the Latin people came, the lords of Alba Longa, the walls of noble Rome.\n\nMuse, tell me the cause.\n\nVirgil begins where Homer began, and then turns it: not a man's rage, but a man's duty, and the price it takes out of him." },
  { title: "In the middle of the journey", source: "Dante, Inferno I (Kline trans.)", text: "In the middle of the journey of our life, I came to myself, in a dark wood, where the direct way was lost. It is a hard thing to speak of, how wild, harsh and impenetrable that wood was, so that thinking of it recreates the fear.\n\nIt is scarcely less bitter than death.\n\nDante was thirty-five when he set the poem \u2014 half of the biblical seventy years. He does not say 'my life'. He says 'our life'. The reader is meant to be lost in the wood too." },
  { title: "The fall of Icarus", source: "Ovid, Metamorphoses VIII (Kline trans.)", text: "The boy began to delight in his daring flight, and abandoning his guide, drawn by desire for the heavens, soared higher. His nearness to the devouring sun softened the fragrant wax that held the wings: and the wax melted.\n\nHe flailed with bare arms, but losing his oar-like wings, could not ride the air. Even as his mouth was crying his father's name, it vanished into the dark blue sea.\n\nThe unhappy father, now no longer a father, shouted 'Icarus, Icarus where are you?' Then he caught sight of the feathers on the waves, and cursed his inventions." },
  { title: "Nothing is more wonderful than man", source: "Sophocles, Antigone (Johnston trans.)", text: "There are many strange and wonderful things, but nothing more strangely wonderful than man.\n\nHe moves across the white-capped ocean seas blasted by winter storms, carving his way under the surging waves engulfing him. With his teams of horses he wears down the unwearied and immortal earth, the oldest of the gods, harassing her, as year by year his ploughs move back and forth.\n\nHe snares the light-winged flocks of birds, herds of wild beasts, creatures from deep seas, trapped in the fine mesh of his hunting nets. O resourceful man, whose skill can overcome ferocious beasts roaming mountain heights." },
  { title: "The Melian dialogue", source: "Thucydides, History of the Peloponnesian War V (Crawley trans.)", text: "The Athenians said: right, as the world goes, is only in question between equals in power, while the strong do what they can and the weak suffer what they must.\n\nThe Melians answered: we speak as we are obliged, since you enjoin us to let right alone and talk only of interest \u2014 that you should not destroy what is our common protection, the privilege of being allowed in danger to invoke what is fair and right.\n\nAnd you are as much interested in this as any, as your fall would be a signal for the heaviest vengeance and an example for the world to meditate upon.\n\nAthens killed the men of Melos and sold the women and children. Within a decade Athens itself had fallen." },
  { title: "Virtue is a mean", source: "Aristotle, Nicomachean Ethics II (Peters trans.)", text: "There is only one way of going right, so that the one is easy and the other hard \u2014 easy to miss the mark and hard to hit. On this account also, then, excess and deficiency are characteristic of vice, hitting the mean is characteristic of virtue.\n\nVirtue, then, is a habit or trained faculty of choice, the characteristic of which lies in moderation or observance of the mean relatively to the persons concerned, as determined by reason, by the reason by which the prudent man would determine it.\n\nNote what it is not: a rule you could write down and follow. It is a skill, and like every skill it is learned by doing it badly first." },
  { title: "On repaying a kindness", source: "Cicero, On Duties I (Miller trans.)", text: "If there shall be obligations already incurred, so that kindness is not to begin with us, but to be requited, still greater diligence is called for; for no duty is more imperative than that of proving one's gratitude.\n\nIf, as Hesiod bids, one is to repay with interest what one has borrowed in time of need, what ought we to do when challenged by an unsought kindness? Shall we not imitate the fruitful fields, which return more than they receive?\n\nFor if we do not hesitate to confer favours upon those who we hope will be of help to us, how ought we to deal with those who have already helped us?" },
  { title: "What education actually is", source: "Epictetus, Discourses I (Long trans.)", text: "What then is education? Education is the learning how to adapt the natural precognitions to the particular things conformably to nature; and then to distinguish that of things some are in our power, but others are not.\n\nIn our power are will and all acts which depend on the will; things not in our power are the body, the parts of the body, possessions, parents, brothers, children, country, and generally all with whom we live in society.\n\nEpictetus was born a slave and lame. He is not being abstract. He is describing the only territory a man in his position actually held." },
  { title: "The thinking reed", source: "Pascal, Pens\u00e9es 347 (Trotter trans.)", text: "Man is but a reed, the most feeble thing in nature; but he is a thinking reed. The entire universe need not arm itself to crush him. A vapour, a drop of water suffices to kill him.\n\nBut, if the universe were to crush him, man would still be more noble than that which killed him, because he knows that he dies and the advantage which the universe has over him; the universe knows nothing of this.\n\nAll our dignity consists, then, in thought. By it we must elevate ourselves, and not by space and time which we cannot fill. Let us endeavour, then, to think well; this is the principle of morality." },
  { title: "The first certainty", source: "Descartes, Principles of Philosophy I (Veitch trans.)", text: "We cannot suppose that we are not while we doubt of the truth of these things; for there is a repugnance in conceiving that what thinks does not exist at the very time when it thinks.\n\nAccordingly, the knowledge, 'I think, therefore I am,' is the first and most certain that occurs to one who philosophizes orderly.\n\nDescartes set out to doubt everything he could possibly doubt, to see what was left standing at the end. This was what was left standing \u2014 not a proof of the world, but a floor to build one on." },
  { title: "Nothing is bred from nothing", source: "Lucretius, On the Nature of Things I (Kelk trans.)", text: "Nature's aspect and decree instructs us that there's nothing that's been bred from nothing. Every mortal's ruled by dread because he sees above and on the land many things whose causes he can't understand, but thinks the gods control.\n\nBut once we know that nothing's bred of nothing, that will show more clearly what we seek \u2014 those things alone that caused all things to fill the global zone without the aid of gods.\n\nIf everything came out of nothing, every kind would spring from everything, yet lacking any seed.\n\nWritten around 55 BC. The argument is that the world is explicable, and that this is a comfort, not a loss." },
  { title: "Look down from above", source: "Marcus Aurelius, Meditations IX.30 (Farquharson trans.)", text: "'Look from above' at the spectacle of myriad herds, myriad rites, and manifold journeying in storm and calm; diversities of creatures who are being born, coming together, passing away.\n\nPonder, too, the life led by others long ago, the life that will be led after you, the life being led in uncivilized races; how many do not even know your name, how many will very soon forget it, and how many who praise you perhaps now will very soon blame you.\n\nHe is writing to himself, at night, in a tent, while commanding the largest army in the world. The point is not that nothing matters. It is that the audience you are performing for does not exist." },
  { title: "Loss is nothing else but change", source: "Marcus Aurelius, Meditations IX.35 (Farquharson trans.)", text: "Loss is nothing else but change. In this Universal Nature rejoices, and by her all things come to pass well. From eternity they came to pass in like fashion, and will be to everlasting in other similar shapes.\n\nWhy then do you say that all things ever came to pass badly, and that all will ever be bad?\n\nThe Stoic move is not to deny that you have lost something. It is to notice that 'loss' and 'change' describe the same event, and that only one of the two words makes you suffer." },
  { title: "Consider your origin", source: "Dante, Inferno XXVI (Kline trans.)", text: "I said: 'O my brothers, who have reached the west, through a thousand dangers, do not deny the brief vigil your senses have left to them \u2014 experience of the unpopulated world beyond the Sun. Consider your origin: you were not made to live like brutes, but to follow virtue and knowledge.'\n\nWith this brief speech I made my companions so eager for the voyage that I could hardly have restrained them, and turning the prow towards morning, we made wings of our oars for that foolish flight.\n\nDante puts this speech in the mouth of a man in hell. It is the most stirring thing in the poem, and it is a warning." },
  { title: "The ring of Gyges", source: "Plato, Republic II (rendered in plain modern English from the Greek)", text: "Suppose there were a ring that made its wearer invisible. Suppose you gave one to a just man and one to an unjust man. Glaucon argues that no one would be strong enough to keep his hands off what was not his \u2014 that both men would end up behaving identically, and that this proves justice is only ever practised under the threat of being seen.\n\nSocrates spends the rest of the Republic answering him.\n\nThe answer, when it finally comes, is not that you would be caught. It is that the unjust man is already being punished, because he has to live inside the sort of person he has become." },
  { title: "The laws of Athens speak", source: "Plato, Crito (rendered in plain modern English from the Greek)", text: "Crito has bribed the guards. Socrates can walk out tonight. Instead he imagines the laws of Athens coming to stand in front of him and asking: do you think a city can survive if the verdicts of its courts are set aside by private individuals whenever they disagree with them?\n\nWe gave you birth, they say, and an education, and seventy years in which you never once left, though the gate was always open. You agreed to us by staying.\n\nHe stays. It is possible to think he was wrong and still see what he was protecting." },
  { title: "The last hour of Socrates", source: "Plato, Phaedo (rendered in plain modern English from the Greek)", text: "He asked whether he might pour a little of the cup as an offering. He was told there was only as much as was needed. Then he raised it and drank it off, quite calmly and without distaste.\n\nMost of us had managed to hold back our tears until then. When we saw him drinking, and then that he had finished it, we could not. Apollodorus had been weeping the whole time, and now he broke out into such a cry that he broke everyone present.\n\nSocrates said: what is this? I sent the women away so that we would not have scenes like this. Be quiet, and be brave." },
  { title: "What makes a thing good?", source: "Plato, Euthyphro (rendered in plain modern English from the Greek)", text: "Socrates asks a simple question and the ground opens under it. Is a thing holy because the gods love it, or do the gods love it because it is holy?\n\nIf the first, then holiness is just a preference, and could have been the opposite. If the second, then holiness is something the gods themselves are answering to, and pointing at them does not explain it.\n\nEuthyphro, who came to court that morning certain he knew exactly what he was doing, leaves without an answer. Twenty-four centuries later the question is still doing damage, which is the surest sign that it is a real one." },
  { title: "Learning is remembering", source: "Plato, Meno (rendered in plain modern English from the Greek)", text: "Socrates calls over a slave boy who has never studied geometry, draws a square in the dust, and asks him how to make one twice its area. The boy guesses. He is wrong. He sees he is wrong. He tries again, and by the end he has found the answer himself, having been told nothing \u2014 only asked.\n\nSocrates says: notice that I taught him nothing. I only questioned. So where did the knowledge come from?\n\nHis answer, that the soul is recovering what it knew before birth, is not one most people take literally now. The observation underneath it survives intact: nobody was ever taught anything. They were only ever helped to find it." },
  { title: "Man is a political animal", source: "Aristotle, Politics I (rendered in plain modern English from the Greek)", text: "A human being is by nature an animal that lives in a city. Anyone who is without a city, not by accident but by nature, is either beneath humanity or above it.\n\nThe proof is that we alone have speech. Other animals have voice, which can signal pain or pleasure. Speech is for something else: for showing what is useful and harmful, and so what is just and unjust. It is the sharing of these that makes a household and a city.\n\nAristotle is not saying people are sociable. He is saying that a person alone is not yet a whole thing \u2014 the way a hand cut from an arm is only called a hand out of politeness." },
  { title: "All men by nature desire to know", source: "Aristotle, Metaphysics I (rendered in plain modern English from the Greek)", text: "All human beings by nature reach out for knowledge. The evidence is the delight we take in our senses, which we love for themselves, quite apart from any use \u2014 and above all the sense of sight.\n\nThe reason is that sight, more than any other sense, shows us things and brings to light the many differences between them.\n\nIt is the opening sentence of the book that named metaphysics, and it is not an argument. It is an observation about children, who ask what a thing is long before they could possibly have a use for the answer." },
  { title: "What tragedy is for", source: "Aristotle, Poetics VI (rendered in plain modern English from the Greek)", text: "Tragedy is the imitation of an action that is serious, complete, and of a certain size; in language made pleasurable; performed rather than narrated; and through pity and fear bringing about the purging of those emotions.\n\nThe most important part is the arrangement of the events. Character comes second. For tragedy is an imitation not of people but of action and life \u2014 and men are happy or wretched by what they do.\n\nThis is the oldest piece of practical writing advice in existence, and it is still the note most often given: you are telling me who he is, show me what he does." },
  { title: "Athens describes itself", source: "Thucydides, History II (rendered in plain modern English from the Greek)", text: "We love beauty without extravagance, and we love wisdom without softness. We use wealth as an opportunity for action rather than as something to boast about, and there is no shame in admitting poverty \u2014 the shame is in not taking steps to escape it.\n\nThe same men attend to their own households and to the business of the city, and even those busy with their trades have a fair understanding of politics. We do not say that a man who takes no interest in public affairs minds his own business. We say he has no business here at all.\n\nPericles delivered this over the first war dead. Thucydides sets the plague immediately after it." },
  { title: "Count no man happy", source: "Herodotus, Histories I (rendered in plain modern English from the Greek)", text: "Croesus, the richest king in the world, showed Solon his treasuries and then asked him who was the happiest man he had ever met. Solon named an Athenian called Tellus, who had good sons, saw his grandchildren grow, and died well in a battle his city won.\n\nPressed for second place, Solon named two brothers who pulled their mother's cart to the temple and died in their sleep that night, at the height of their honour.\n\nCroesus lost his temper. Solon said: I see a great deal of money and I see a king over many men, but I cannot answer your question until I hear how you ended. Count no man happy until he is dead.\n\nWithin fifteen years Croesus had lost his son, his kingdom, and his fortune, and was standing on a pyre saying Solon's name." },
  { title: "Stand out of my sunlight", source: "Plutarch, Life of Alexander (rendered in plain modern English from the Greek)", text: "Alexander, master of Greece and about to invade Asia, went to see Diogenes the Cynic, who was lying in the sun. The philosopher looked at him without getting up.\n\nAlexander asked whether there was anything he wanted. Diogenes said: yes \u2014 move a little to the side, you are blocking the sun.\n\nAlexander's companions laughed at the old man on the way back. Alexander did not. He said: if I were not Alexander, I would want to be Diogenes.\n\nThe joke is that Diogenes was the only man alive who wanted nothing Alexander could take away, and both of them knew it." },
  { title: "Wisdom comes through suffering", source: "Aeschylus, Agamemnon (rendered in plain modern English from the Greek)", text: "Zeus, who set men on the road to understanding, who laid it down that wisdom comes by suffering.\n\nEven in sleep, pain that remembers falls drop by drop upon the heart, and against our will, and by a hard grace, comes sense.\n\nThe chorus is not saying that suffering is good, or deserved, or a lesson someone arranged for you. It is saying something bleaker and more useful: that understanding does arrive, that it arrives late, that it arrives without being asked for, and that nobody would have chosen the price." },
  { title: "Time, and what it is", source: "Augustine, Confessions XI (rendered in plain modern English from the Latin)", text: "What, then, is time? If nobody asks me, I know. If I want to explain it to somebody who asks, I do not know.\n\nThis much I can say with confidence: if nothing passed away there would be no past, and if nothing were coming there would be no future, and if nothing existed there would be no present. So how can the past and the future be, when the past is no longer and the future is not yet?\n\nAnd the present \u2014 if it were always present and never moved on into the past, it would not be time at all. It would be eternity.\n\nWritten around 400 AD, and still the clearest statement of the problem anybody has managed." },
  { title: "The fields of memory", source: "Augustine, Confessions X (rendered in plain modern English from the Latin)", text: "I come to the fields and vast palaces of memory, where the treasures of countless images are kept, carried in by the senses. Everything I have thought, by enlarging or shrinking or altering what the senses reached, is stored there \u2014 and whatever else has been put in and not yet swallowed up and buried.\n\nWhen I go in, I ask for a thing to be brought out, and some things come at once, and some have to be searched for a long while, as if they were dragged out of hidden compartments. And others rush out in a crowd when something else is being looked for, as if to say, 'Perhaps it is us you want?'\n\nAnd I brush them away with the hand of my heart until the thing I want clears and comes out." },
  { title: "The wheel of Fortune", source: "Boethius, The Consolation of Philosophy II (rendered in plain modern English from the Latin)", text: "This is my art, says Fortune. This is the game I never stop playing. I turn the wheel, and I delight to bring the low up and the high down. Climb on, if you like \u2014 but on the condition that you do not complain when the turn of my wheel takes you back down.\n\nDid you not know my ways? When Croesus was handed over to Cyrus and set on the fire, did the rain that saved him come from anywhere but here?\n\nBoethius wrote this in a cell, awaiting execution on a charge he denied, having been the second most powerful man in Italy the previous year. It is not a theory. It is a man arguing himself into being able to sleep." },
  { title: "On crowds", source: "Seneca, Letters to Lucilius 7 (rendered in plain modern English from the Latin)", text: "You ask what you should avoid most of all. Crowds. You cannot yet be trusted with one.\n\nI never come home with the character I left with. Something I had put in order is disturbed, something I had driven out comes back. Nothing is so damaging to good habits as loafing at a show, because vice slips in easily while you are being entertained.\n\nI came home greedier, more ambitious, more self-indulgent \u2014 and crueller and less human, because I had been among human beings.\n\nWithdraw into yourself as far as you can. Keep company with those who will make you better, and let in those you can make better. It works both ways: men learn while they teach." },
  { title: "Practise poverty", source: "Seneca, Letters to Lucilius 18 (rendered in plain modern English from the Latin)", text: "Set aside a certain number of days on which you will be content with the plainest food and the roughest clothing, and say to yourself: is this what I was afraid of?\n\nIt is precisely in times of security that the mind should prepare itself for hard times. Make friends with the pallet bed and the coarse cloak while fortune is being generous, so that if she ever takes offence you will already know the ground.\n\nThe point is not to suffer. It is to find out, while it is still your own decision, exactly how little you need \u2014 so that the possibility of losing things stops governing you." },
  { title: "Friendship, of all things", source: "Epicurus, Principal Doctrines (rendered in plain modern English from the Greek)", text: "Of all the things that wisdom provides for a complete and happy life, by far the greatest is friendship.\n\nThe same conviction that gives us confidence there is nothing terrible in death, and nothing eternal to fear, shows us that friendship is the surest of the goods that can be had within the limits of a lifetime.\n\nEpicurus is routinely remembered as the philosopher of pleasure, which he was, and routinely misremembered as the philosopher of luxury, which he was not. He lived in a garden outside Athens, ate plainly, admitted women and slaves as students, and named the highest pleasure available to a human being as the company of people who wish you well." },
  { title: "Of Studies", source: "Francis Bacon, Essays (1625) \u2014 written in English", text: "Studies serve for delight, for ornament, and for ability. Their chief use for delight is in privateness and retiring; for ornament, is in discourse; and for ability, is in the judgment and disposition of business.\n\nRead not to contradict and confute; nor to believe and take for granted; nor to find talk and discourse; but to weigh and consider.\n\nSome books are to be tasted, others to be swallowed, and some few to be chewed and digested: that is, some books are to be read only in parts; others to be read, but not curiously; and some few to be read wholly, and with diligence and attention.\n\nReading maketh a full man; conference a ready man; and writing an exact man." },
  { title: "Why I went to the woods", source: "Henry David Thoreau, Walden (1854) \u2014 written in English", text: "I went to the woods because I wished to live deliberately, to front only the essential facts of life, and see if I could not learn what it had to teach, and not, when I came to die, discover that I had not lived.\n\nI did not wish to live what was not life, living is so dear; nor did I wish to practise resignation, unless it was quite necessary. I wanted to live deep and suck out all the marrow of life, to live so sturdily and Spartan-like as to put to rout all that was not life.\n\nHe stayed two years, two months and two days, and walked into town regularly. Both facts are usually held against him, and neither touches the sentence." },
  { title: "The choice of Heracles", source: "Xenophon, Memorabilia II (rendered in plain modern English from the Greek)", text: "Heracles, at the age where the young decide what kind of life to lead, went out to a quiet place and sat down. Two women came to him.\n\nThe first promised the shortest and pleasantest road: no war, no work, no worry \u2014 only the question of what would be most agreeable to eat, to drink, and to see. Her friends, she admitted, called her Happiness. Her enemies called her Vice.\n\nThe second offered nothing but the truth about the gods' terms: that nothing good and nothing admirable is given to anybody without effort and care. If you want the earth to bear for you, tend it. If you want a body that obeys you, train it.\n\nThe story is two and a half thousand years old and has never once needed updating." },
  { title: "Work, and the hunger that follows", source: "Hesiod, Works and Days (rendered in plain modern English from the Greek)", text: "The gods keep what feeds a man hidden. Otherwise you could work one day and have enough for a year, and hang your rudder up over the fire, and let the oxen and the hard-working mules go idle.\n\nBadness is easy to get, in quantity. The road is smooth and it lives close by. But the gods have put sweat in front of goodness, and the path to it is long and steep and rough at the start \u2014 though when you reach the top it becomes easy, hard as it was before.\n\nHesiod was a farmer writing to a brother who had cheated him out of land and then run short. It is the oldest surviving piece of advice from one working man to another." },
  { title: "The Master on learning", source: "Confucius, Analects II (rendered in plain modern English from the Chinese)", text: "The Master said: learning without thinking is wasted labour; thinking without learning is dangerous.\n\nThe Master said: when you know a thing, hold that you know it; and when you do not know a thing, allow that you do not know it. This is knowledge.\n\nThe Master said: at fifteen I set my mind on learning. At thirty I stood firm. At forty I had no more doubts. At fifty I knew the will of heaven. At sixty my ear was obedient. At seventy I could follow what my heart desired without overstepping the line.\n\nThe last saying takes fifty-five years to complete, and he is the one who counted." },
  { title: "The first definitions", source: "Euclid, Elements I (Casey's edition)", text: "A point is that which has no parts. A line is length without breadth. The extremities of a line are points. A straight line is one which lies evenly between its extreme points. A surface is that which has length and breadth only.\n\nAnd then the postulates. Let it be granted that a straight line may be drawn from any one point to any other point; that a terminated straight line may be produced to any length; that a circle may be described with any centre at any distance from that centre.\n\nFrom five definitions of this kind and five requests of this kind, everything else follows. It is the most successful book ever written after the Bible, and this is all it starts with." },
  { title: "On coming back down", source: "Plato, Republic VII (rendered in plain modern English from the Greek)", text: "Suppose the freed prisoner went back into the cave and sat down in his old seat. His eyes, full of sunlight, would be useless in the dark. He would be clumsy at the shadow game he used to be good at, and the others would say that he had gone up and come back with his sight ruined, and that it was not worth anyone's while to go up.\n\nAnd if they could get their hands on the man who was trying to release them and lead them up, they would kill him.\n\nPlato wrote this about thirty years after the city of Athens executed his teacher. It is the only place in the Republic where the argument stops being an argument." },
  { title: "What a friend is for", source: "Cicero, On Friendship (Laelius) (rendered in plain modern English from the Latin)", text: "Friendship is agreement on all things human and divine, together with goodwill and affection \u2014 and I am inclined to think that, wisdom apart, nothing better has been given to man.\n\nIt makes good fortune brighter by sharing it, and lightens bad fortune by dividing it. And it has this, which is greater than everything else: it sends a good hope forward into the future, and does not let the spirit weaken or fall.\n\nFor whoever looks at a true friend looks at something like a copy of himself. So the absent are present, and the poor are rich, and the weak are strong, and \u2014 which is harder to say \u2014 the dead are alive.\n\nCicero wrote it after the murder of his closest friend, and his own murder followed within two years." },
  { title: "A day well spent", source: "Montaigne, Essays III (Cotton trans.)", text: "There is nothing so beautiful and legitimate as to play the man well and properly, no knowledge so hard to acquire as the knowledge how to live this life well and naturally; and the most barbarous of our maladies is to despise our being.\n\nHe who would separate his soul from his body, let him do it boldly if he can, at the time when the body is sick, so as to relieve it of the contagion. At all other times, let the soul assist and favour the body, and not refuse to take part in its natural pleasures.\n\nMontaigne retired at thirty-eight to write a book about himself, and accidentally invented the essay while trying to work out what he actually thought." },
  { title: "The god you cannot describe", source: "Thomas Aquinas, Summa Theologica I (rendered in plain modern English from the Latin)", text: "We cannot know what God is, but only what he is not; so we cannot consider how he is, but rather how he is not.\n\nTherefore we must consider the ways in which he does not exist, rather than the ways in which he does \u2014 by removing from him what does not belong to him, such as composition, motion, and the rest.\n\nAquinas wrote around two million words on the subject. Near the end of his life he stopped mid-sentence and never wrote again, saying only that everything he had written seemed to him like straw. Both facts belong to the same man, and neither cancels the other." },
];

